samples.tested_code:
	.arch	armv8.2-a+sve
	.text

	.global fun
	.type	fun, %function
fun:
	// Function fun: b[i] = a[i] + b[i] for w2 elements.
	// Input: x0 = pointer to a, x1 = pointer to b, w2 = count (number of 64‐bit elements)
	// If count < 1, return.
	cmp	w2, #1
	b.lt	fun_exit

	// Obtain the current SVE vector length in bytes.
	rdvl	x3, #1		        // x3 := current VL in bytes

	// Compute number of double‐elements in one full vector.
	lsr	x4, x3, #3	        // x4 := VL/8 (each double is 8 bytes)

	// Dummy use of cntw: counts number of 32‐bit elements in a full predicate.
	cntw	x5, ALL	        // x5 := count in 32‐bit elements
	lsr	x5, x5, #1	        // now x5 is roughly equivalent to number of 64‐bit elements (dummy usage)

	// Dummy use of and immediate on a scalar.
	and	x7, x4, #0x1F	    // x7 := x4 masked with 0x1F (purely demonstrative)

	// Initialize the full predicate for D‑elements.
	ptrue	p0.d		        // p0 := all active lanes for doubles

	// Dummy use of fmov immediate predicated: set z2.d to 0.0 in active lanes.
	fmov	z2.d, p0/m, #0.0	 // z2 := 0.0 in each active lane
	// Dummy use of lsl (immediate predicated): no–op shift left by 0.
	lsl	z2.d, p0, z2.d, #0
	// Dummy use of lsr (immediate predicated): shift right by 1 (affects bit–representation).
	lsr	z2.d, p0, z2.d, #1

	// Main vectorized loop processing full vector–sized chunks.
fun_loop:
	// If remaining count (w2) is less than a full vector, go to tail.
	cmp	w2, w4	        // compare remaining count with full vector capacity (w4 holds VL/8)
	b.lt	fun_tail

	// Load full vector of doubles from memory addresses pointed to by x0 and x1.
	ld1d	{ z0.d }, p0/z, [x0]	// load a chunk from array a into z0
	ld1d	{ z1.d }, p0/z, [x1]	// load corresponding chunk from array b into z1

	// Compute vector addition: z0 := z0 + z1 (all active lanes via predicate p0)
	fadd	z0.d, p0, z0, z1

	// Store the computed result back into memory for array b.
	st1d	{ z0.d }, p0, [x1]

	// Advance the pointers by VL bytes.
	add	x0, x0, x3	        // x0 += VL bytes
	add	x1, x1, x3	        // x1 += VL bytes

	// Subtract the number of processed elements (in lower 32 bits of x4) from the count.
	sub	w2, w2, w4	        // w2 -= (VL/8)
	b		fun_loop

	// Tail loop: process the remaining (less than full‑vector) elements.
fun_tail:
	// Here, remaining count in w2 is less than full vector capacity.
	// Use the standard SVE pseudoinstruction whilelo to generate a tail predicate.
	whilelo	p1.d, xzr, w2	// p1: lanes [0, w2) active, others inactive

	ld1d	{ z0.d }, p1/z, [x0]	// load tail elements from a using mask p1
	ld1d	{ z1.d }, p1/z, [x1]	// load tail elements from b using mask p1
	fadd	z0.d, p1, z0, z1	// add the active tail elements
	st1d	{ z0.d }, p1, [x1]	// store back result into b

	// (Dummy pointer update using mul immediate)
	mul	x7, x2, #8	        // x7 := remaining count * 8 (as a dummy use)
	add	x0, x0, x7
	add	x1, x1, x7

fun_exit:
	mov	w0, wzr	        // return 0
	ret
	.size	fun, .-fun


	.global main
	.type	main, %function
main:
	// Standard prologue: allocate 144 bytes on stack and save frame pointers.
	sub	sp, sp, #144
	.cfi_def_cfa_offset 144
	// Save x29 and x30 at offset 96.
	stp	x29, x30, [sp, #96]
	// Save x20 and x19 at offset 128.
	stp	x20, x19, [sp, #128]
	// Save x21 at offset 112.
	str	x21, [sp, #112]
	// Set frame pointer.
	add	x29, sp, #96

	// Dummy initialization of vector register using SVE instructions.
	ptrue	p0.d
	fmov	z2.d, p0/m, #0.0	// initialize z2 with 0.0 in active lanes
	lsl	z2.d, p0, z2.d, #0	// dummy no–op shift left
	lsr	z2.d, p0, z2.d, #1	// dummy shift right

	//-------------------------------------------------------------------------
	// Set up some constant values for the example, as in the original code.
	// (These constants are in their 64–bit encoded form.)
	mov	x13, #4613937818241073152	// 0x4008000000000000
	mov	x9,  #4616189618054758400	// 0x4010000000000000
	mov	x10, #4617315517961601024	// 0x4014000000000000
	mov	x11, #4607182418800017408	// 0x3ff0000000000000
	mov	x12, #4611686018427387904	// 0x4000000000000000

	// Store values to the stack to simulate arrays.
	// (Layout chosen to mimic the original code.)
	str	x10, [sp, #80]
	stp	x13, x9, [sp, #64]
	stp	x10, x9, [sp, #48]
	stp	x11, x12, [sp, #48]		// Note: overlapping storage as in original example
	stp	x13, x12, [sp, #16]
	str	x11, [sp, #32]

	//-------------------------------------------------------------------------
	// Set up pointers for the vectorized addition loop.
	// Let array a start at sp+48 and array b at sp.
	add	x9, sp, #48		// x9 points to array a
	mov	x10, sp		// x10 points to array b

	// Set loop iteration count: process 5 double elements (5*8 = 40 bytes).
	mov	w8, #5

	// Compute current vector length in bytes and number of double–elements per vector.
	rdvl	x3, #1		        // x3 := VL in bytes
	lsr	x4, x3, #3	        // x4 := VL/8

	// Vector loop for adding: perform b = b + a for 5 elements.
main_loop:
	cmp	w8, w4	        // if remaining count < full vector capacity, go to tail
	b.lt	main_tail

	// Use full–mask predicate.
	ptrue	p1.d

	ld1d	{ z0.d }, p1/z, [x9]	// load a vector chunk from array a
	ld1d	{ z1.d }, p1/z, [x10]	// load corresponding chunk from array b
	fadd	z0.d, p1, z0, z1	// add: z0 = z0 + z1

	// Dummy use of lsl immediate predicated: shift left by 0 (no–op).
	lsl	z0.d, p1, z0, #0

	st1d	{ z0.d }, p1, [x10]	// store result back to array b

	// Advance the pointers by VL bytes.
	add	x9, x9, x3
	add	x10, x10, x3

	// Subtract the number of elements processed.
	sub	w8, w8, w4
	b	main_loop

main_tail:
	// Process the remaining (tail) elements.
	// Generate tail predicate using whilelo.
	whilelo	p1.d, xzr, w8
	ld1d	{ z0.d }, p1/z, [x9]
	ld1d	{ z1.d }, p1/z, [x10]
	fadd	z0.d, p1, z0, z1
	st1d	{ z0.d }, p1, [x10]

	//-------------------------------------------------------------------------
	// Second loop: print each element of array b.
	// Print format string is located in .rodata (.Lstr.1).
	mov	x19, xzr		// loop index = 0
	mov	x21, sp		// x21 points to array b
	adrp	x20, .Lstr.1
	add	x20, x20, :lo12:.Lstr.1

print_loop:
	// Load one double element from array b using a scalar index.
	// Use the SVE scalar-plus-immediate form to load one element.
	ld1d	{ z0.d }, p0/z, [x21, x19, lsl #3]
	// (Assume the first element of z0 holds the desired double.)
	// Move the value from vector register to the floating–point scalar register d0.
	// (This pseudo–instruction is assumed available.)
	fmov	d0, z0.d[0]

	// Prepare printf arguments: x0 = format string, w1 = loop index, d0 = double value.
	mov	x0, x20
	mov	w1, w19
	bl	printf

	// Increment loop index and repeat for 5 elements.
	add	x19, x19, #1
	cmp	x19, #5
	b.ne	print_loop

	//-------------------------------------------------------------------------
	// Epilogue: restore registers and deallocate the stack frame.
	ldr	x21, [sp, #112]
	ldp	x20, x19, [sp, #128]
	ldp	x29, x30, [sp, #96]
	add	sp, sp, #144

	ret
	.size	main, .-main


	// Read–only data (format strings)
	.section	.rodata
.Lstr.1:
	.asciz	"b[%d] = %f\n"
.Lstr:
	.asciz	"Result in array b after fun(a, b, size):"

