  mov w0, #61569
  movk w0, #762, lsl #16
  bl malloc
  mov x20, x0

  // Allocate the second buffer (size = (3051<<16)+49668).
  mov w0, #49668
  movk w0, #3051, lsl #16
  bl malloc
  mov x19, x0

  // Call memset to fill the first buffer (at address x20+2) with ones.
  add x0, x20, #2
  mov w1, #1
  mov w2, #61567     // Size = (762<<16)+61567 (almost the same as above)
  movk w2, #762, lsl #16
  bl memset

  // --- Begin vectorized computation using SVE ---
  // We will use SVE to process (at least) one block of 32-bit words.
  // (Note: for simplicity we assume that the memory at x20 is large enough and
  //  properly aligned for a vector load/store of 32-bit quantities.)

  // Set a predicate covering ALL lanes for 32‑bit elements.
  ptrue p0.s

  // Load 32‑bit words from the first buffer into vector register Z0.
  ld1w {z0.s}, p0, [x20]

  // Multiply every element by the constant 3.
  // (This uses the SVE “MUL (immediate)” instruction.)
  mul z0.s, z0.s, #3

  // Now perform a bitwise AND with an immediate value.
  // Here we use the constant 0xFF (which is a valid immediate pattern, repeating every 8 bits).
  and z0.s, z0.s, #0xFF

  // Store the result vector into the second buffer.
  st1w {z0.s}, p0, [x19]

  // Reduce the vector by adding all its active 32‑bit elements.
  // (ADDV produces a scalar result from a vector reduction.)
