// This file is built for AArch64 with SVE enabled.
// It defines two functions, “is_pan” and “main”, that use SVE vector registers
// (Z0–Z31) and predicate registers (P0–P15) as well as the following SVE
// instructions: uzp1, umaxv, fmov, bic, and, and sxtw.
//
// “is_pan” allocates an array of 10 32‐bit words on the stack,
// initializes it to 0 and (if its input argument in X0 is nonzero)
// fills it with 1’s. It then uses the SVE “umaxv” reduction to check whether 
// the maximum value in the array is 1 (in which case it returns 1, else 0).
//
// “main” calls is_pan then executes several SVE operations:
//   – fmov is used to broadcast floating‐point immediates into vector registers,
//   – uzp1 interleaves even elements from two vectors,
//   – and and bic (with appropriate immediate values) perform bit‐manipulation on a vector,
//   – sxtw sign‐extends 32‐bit integers in a vector to 64‐bit values,
//   – a second umaxv example reduces a vector to its unsigned maximum.
// Finally, main calls printf (using the standard C library) to print the result.
//

	.text
	.global is_pan
	.type is_pan, @function
is_pan:
	// Function prologue: save frame pointer and link register.
	stp	x29, x30, [sp, #-16]!		
	mov	x29, sp
	// Allocate 48 bytes on the stack to hold an array of 10 integers.
	sub	sp, sp, #48

	// Setup a predicate for the first 10 lanes (each lane = 32-bit) in predicate P0.
	whilelo	p0.s, xzr, #10			
	// Duplicate zero into every 32‐bit lane of vector register Z0.
	dup		z0.s, wzr				
	// Store the zeros into memory: initializes the 10-word array with 0.
	st1w	{ z0.s }, p0, [sp]		

	// If X0 equals zero, skip updating the array.
	cmp		x0, #0				
	beq		ispan_skip_update		

	// Otherwise, fill the array with ones.
	mov		w1, #1				
	dup		z0.s, w1				
	st1w	{ z0.s }, p0, [sp]		

ispan_skip_update:
	// Load the array from memory into vector register Z1.
	ld1w	{ z1.s }, p0, [sp]		
	// Use SVE’s unsigned maximum reduction: compute max{Z1.s}'s active lanes; result in S2.
	umaxv	s2, p0/m, z1.s			
	// Compare the reduction result with 1.
	cmp		s2, #1				
	// Set W0 to 1 if equal, or 0 otherwise.
	cset	w0, eq				
	// Deallocate the local array and restore FP and LR.
	add		sp, sp, #48			
	ldp		x29, x30, [sp], #16	
	ret

	.global main
	.type main, @function
main:
	// Function prologue.
	stp		x29, x30, [sp, #-16]!		
	mov		x29, sp
	sub		sp, sp, #32				// Allocate 32 bytes for main’s frame.

	// Call is_pan with an argument of 1 (nonzero) so that the array is filled with ones.
	mov		x0, #1				
	bl		is_pan					
	// The result from is_pan is now in W0.

	// --- Begin SVE instruction demonstrations in main ---

