        .globl  powm
        .type   powm, @function
powm:
        // Function prologue: spill frame pointer, LR, and x19 (used for base)
        stp     x29, x30, [sp, #-32]!
        stp     x19, x20, [sp, #-16]!     // (x20 is a scratch spill)
        mov     x29, sp

        // --- Begin SVE dummy block ---
        // Set up a full–active predicate for 64‐bit (doubleword) elements.
        ptrue   p0.d
        // Create an index vector in z1.d starting at 0 (using xzr as “step”)
        index   z1.d, #0, xzr
        // Shift left z1.d by 2 bits (i.e. multiply each element by 4)
        lsl     z1.d, p0/m, z1.d, #2
        // Mask the lower 32 bits of each element (dummy “and” operation)
        and     z1.d, z1.d, #0xFFFFFFFF
        // Perform a multiply–subtract on z1.d (computes: 0 - (z1*d z1))
        mls     z1.d, p0, z1.d, z1.d
        // --- End SVE dummy block ---

        // If exponent (w1) == 0 then go to base case.
