        beq     powm_base_case

        // Save original base in w19.
        mov     w19, w0

        // Test the least–significant bit of exponent.
        tbnz   w1, #0, powm_odd

        // ---------- EVEN exponent path ----------
        cmp     w1, #0          // (Redundant test; here w1 is even and > 0)
        mov     w0, w19
        cinc    w8, w1, lt      // Conditionally increment if comparison is less-than.
        asr     w1, w8, #1      // Divide exponent by 2.
        bl      powm            // Recursive call.
        mul     w8, w0, w0      // Square the result.
        mov     w9, #19923
        movk    w9, #4194, lsl #16
        mov     w10, #250
        umull   x9, w8, w9
        lsr     x9, x9, #36
        msub    w0, w9, w10, w8
        b       powm_epilogue

powm_odd:
        // ---------- ODD exponent path ----------
        sub     w1, w1, #1
        mov     w0, w19
        bl      powm
        mov     w8, #19923
        mul     w9, w0, w19
        movk    w8, #4194, lsl #16
        smull   x8, w9, w8
        lsr     x10, x8, #63
        asr     x8, x8, #36
        // Ensure w10 is set (as in even branch) before use.
        mov     w10, #250
        add     w8, w8, w10
        msub    w0, w8, w10, w9

powm_base_case:
        // Base case: exponent==0 --> return 1.
        mov     w0, #1

powm_epilogue:
        // Epilogue: restore spilled registers and return.
        ldp     x19, x20, [sp], #16
        ldp     x29, x30, [sp], #32
        ret

