        stp     x28, x27, [sp, #16]
        stp     x26, x25, [sp, #32]
        stp     x24, x23, [sp, #48]
        stp     x22, x21, [sp, #64]
        stp     x20, x19, [sp, #80]
        mov     x29, sp

        // Reserve 4000 bytes for a local buffer.
        sub     sp, sp, #4000

        // Call memset to zero–initialize 2000 bytes at address (sp+2000).
        mov     w1, wzr
        add     x0, sp, #2000          // destination pointer for memset
        add     x1, sp, #2000          // source argument (dummy, not used by memset)
        mov     w2, #2000
        bl      memset

