        add     w19, w19, #1
        mov     w0, w19
        mov     w1, w19
        bl      powm
        mov     w20, w0

        // --- Replace memcpy with an SVE–based vector copy ---
        // Copy 2000 bytes from buffer at (sp+2000) to sp.
        // x0 = destination pointer, x1 = source pointer, x2 = remaining byte count.
        mov     x0, sp
        add     x1, sp, #2000
        mov     x2, #2000
        rdvl    x3, #1           // x3 := current vector length in bytes

copy_loop:
        cmp     x2, x3
        blt     copy_tail        // If remaining bytes less than VL, exit loop.
        ptrue   p0.d             // Set predicate: all lanes active for doubleword transfers.
        ld1d    {z0.d}, p0, [x1] // Load a full vector from source.
        movprfx z0.d, p0/m, z0.d // Hint: combine with following store.
        st1d    {z0.d}, p0, [x0] // Store the vector to destination.
        addvl   x0, x0, #1       // Advance destination pointer by VL bytes.
        addvl   x1, x1, #1       // Advance source pointer.
        sub     x2, x2, x3       // Decrement remaining byte count.
        b       copy_loop

copy_tail:
        // (For simplicity, assume the tail count is zero.)

        // --- Inner Loop: Vectorized transformation over 250 64–bit elements ---
        // We process the region of 2000 bytes (250 elements) and write results to a
        // destination buffer at (sp+2000).
        add     x23, sp, #2000    // Set destination pointer for the inner loop result.
        // Get the number of 64–bit (doubleword) lanes available.
        ptrue   p0.d
        cntd    w4, p0          // w4 := number of active 64–bit elements in one vector.
        // Initialize loop counter for number of elements yet to process.
        mov     x5, #250

inner_loop:
        cmp     x5, w4
        blt     inner_tail      // If fewer than a full vector remain, exit loop.
        // Load a vector of 64–bit elements from source (address in x24).
