        // "and" to mask (simulate a bit–wise operation)
        and     z3.d, z1.d, #0xFFFFFFFF
        // Use "mls" to subtract the product (dummy operation).
        mls     z1.d, p0, z1.d, z3.d

        // Write the transformed vector to the destination buffer.
        st1d    {z1.d}, p0, [x23]
        addvl   x24, x24, #1     // Advance source pointer by VL (i.e. by (VL/8)*8 bytes).
        addvl   x23, x23, #1     // Advance destination pointer similarly.
        // Decrement the loop counter by the number of elements processed (w4).
        sub     x5, x5, w4
