// aarch64+sve version of the provided code.
// This code uses SVE registers Z0–Z31 and predicate registers P0–P15,
// and it forces use of the SVE instructions: rdvl, ptrue, lsr, cnth, ld1w, uaddv, and fmov.
// In this translation the originally “complex” inner loop (which performed some computed memory updates)
// is replaced by two vectorized loops: one that “increments” every 32‐bit element of the allocated array
// (simulating the memory–update phase) and a second that “counts” (reduces) the number of elements equal to 10.
// Standard library calls (malloc, memset, printf) are used.
// Compile with an SVE–enabled aarch64 toolchain.

	.text
	.file	"e135.c"
	.globl	main
	.p2align	2
	.type	main,@function
main:
	// Prologue: reserve stack frame and save non–volatile registers.
	stp	x29, x30, [sp, #-32]!
	stp	x20, x19, [sp, #16]
	mov	x29, sp

	// Compute malloc size:
	//   The original code used:
	//     mov	w0, #2304
	//     movk	w0, #61, lsl #16
	// which produces  (61<<16) | 2304 = 0x3D0900 = 4000000 bytes.
	// Also, the original x20 is set so that the number of 32‐bit words (4000000/4) is 1000000.
	mov	w0, #2304
	movk	w0, #61, lsl #16
	// Set x20 = number of 32‐bit elements (= 1000000); see original:
	mov	w20, #16960
	movk	w20, #15, lsl #16

	bl	malloc              // Allocate 4000000 bytes.
	// Save the base pointer (for later re–scanning) in x21.
	mov	x21, x0
	// x19 will be used as our update pointer.
	mov	x19, x0

	// Call memset(x19, 0, 4000000)
	mov	w2, #2304
	movk	w2, #61, lsl #16
	mov	w1, wzr
	bl	memset

	// --- Set up SVE context for the two vector loops ---
	// ptrue: set predicate p0 for all active 32–bit lanes.
	ptrue	p0.s

	// Use cnth to get the number of active lanes (in elements) and save it in x3.
	cnth	x3, p0, #1           // x3 := (number of active 32–bit lanes) [for debugging if desired]
	// Now use rdvl to get the implementation–defined vector length in bytes;
	// divide by 4 (using lsr) to get the chunk size (number of 32–bit words per iteration).
	rdvl	x7, #1              // x7 := VL in bytes (VL is the scalable vector‐length)
	lsr	x7, x7, #2           // x7 := VL/4 (number of 32–bit elements per full vector iteration)

	// --- Vectorized INCREMENT loop ---
	// This loop walks over the entire array (1000000 words) and increments
	// each element by 1. (In the original code a computed update was done.)
	// x20 is the remaining element count.
	// x19 is the current pointer.
	// Note: We use ld1w to load a vector, fmov to form a constant vector "1", then vector–add and st1w.
	//
	// At this point, x20 = 1000000.
inc_loop:
	cmp	x20, x7             // Do we have at least one full vector?
	b.lt	inc_tail            // If not, jump to the tail loop.
	ld1w	{ z0.s }, p0, [x19]  // Load a full vector (32–bit elements) from memory.
	fmov	z1.s, p0/M, #1      // Set every active element of z1 to 1.
	// Vector addition: z0 = z0 + z1.
	add		z0.s, z0.s, z1.s
	// Store the updated vector back:
	st1w	{ z0.s }, p0, [x19]
	// Advance the pointer by (chunk_size * sizeof(word)) bytes.
	mul		x4, x7, #4        // x4 = number of bytes in one vector chunk.
	add		x19, x19, x4
	// Decrease remaining count by the full chunk.
	sub		x20, x20, x7
	b		inc_loop

inc_tail:
	// Tail loop: process one element at a time.
	cbz		x20, inc_done    // if no remainder, we are done.
tail_inc:
		ldr	w5, [x19]
		add		w5, w5, #1
		str		w5, [x19]
		add		x19, x19, #4
		sub		x20, x20, #1
		cbnez	x20, tail_inc
inc_done:

	// --- Vectorized COUNT loop ---
	// We now want to count the number of elements equal to 10.
	// Reset x19 to the base pointer (stored earlier in x21)
	mov		x19, x21
	// (Re)initialize the total element count to 1000000.
	mov		x20, #1000000
	// Clear the accumulator (will hold the count).
	mov		x4, xzr

count_loop:
	cmp		x20, x7
	b.lt		count_tail
	ld1w	{ z0.s }, p0, [x19]   // Load a vector of words.
	fmov	z1.s, p0/M, #10     // Set each active lane of z1 with constant 10.
	// Compare: set predicate p1.s true where z0.s == z1.s.
	cmpeq	p1.s, z0.s, z1.s
	// Use fmov (immediate predicated) to force 1 into each lane where p1 is true.
	fmov	z2.s, p1/M, #1
	// Sum the vector “ones” horizontally with uaddv. The result is placed in s3.
	uaddv	s3, p0, z2.s
	// Transfer the 32–bit result (in s3) to a general–purpose register.
	fmov	x5, s3
	// Accumulate into x4.
	add		x4, x4, x5
	// Advance pointer and decrease count.
	mul		x6, x7, #4
	add		x19, x19, x6
	sub		x20, x20, x7
	b		count_loop

count_tail:
	cbz		x20, count_done
tail_count:
		ldr		w7, [x19]
		cmp		w7, #10
		// Use csel: if equal then set w8=1, otherwise 0.
		csel	w8, wzr, #1, eq
		add		x4, x4, x8
		add		x19, x19, #4
		sub		x20, x20, #1
		cbnz	x20, tail_count
count_done:
	// x4 contains the count.
	// Prepare to call printf with a format string and the count.
	adr		x0, .Lstr
	mov		x1, x4
	bl		printf

	// Return 0.
	mov		w0, wzr
	// Epilogue: restore non–volatile registers and return.
	ldp		x20, x19, [sp, #16]
	ldp		x29, x30, [sp], #32
	ret

	// Format string data.
.Lstr:
	.asciz	"%i\n"
	.size	.Lstr, .- .Lstr
	.size	main, .-main

