main:
        // Function prologue.
        stp     x29, x30, [sp, #-16]!
        mov     x29, sp

        // Allocate 5000 bytes.
        mov     w0, #5000
        bl      malloc
        // Save the original pointer for freeing later.
        mov     x19, x0
        // Use x20 as our working pointer.
        mov     x20, x0

