        // Set up SVE predicate and loop‐bound values.
        //
        // ptrue – set predicate register (for 64‐bit, i.e. doubleword, lanes)
        ptrue   p0.d            
        //
        // rdvl – read current vector length (VL in bytes).
        rdvl    x1, #1          
        //
        // cntw – count the number of active (doubleword) lanes.
        // (Use the 32‐bit alias so that the result is zero‐extended.)
        cntw    w2, p0          
        //
        // We assume 5000 bytes holds 625 doublewords.
        mov     x3, #625        

        //-------------------------------------------------------------------------
        // Vectorized loop using SVE instructions.
        //
        // In each iteration we:
        //  1) Load a vector of 64‐bit elements using ld1d.
        //  2) Multiply each element by 3.
        //  3) Bit‐mask each element with 0xff.
        //  4) Compute the unsigned “high‐half” product of (value×value) via UMULH.
        //  5) Combine the results via MLS (multiply–subtract).
        //  6) (Use movprfx as a hint.)
        //  7) Store the vector back with st1d.
        //  8) Advance our pointer by one vector length (using addvl).
vector_loop:
