        ld1d    {z0.d}, p0/z, [x20]     // load a vector of 64‐bit elements.
        mul     z0.d, z0.d, #3          // vector multiply by immediate 3.
        and     z0.d, z0.d, #0xff        // vector bitwise AND with 0xff.
        umulh   z1.d, p0/m, z0.d, z0.d   // z1 = high half of (z0 * z0), predicated.
        mls     z0.d, z0.d, z0.d, z1.d    // compute: z0 = z1 – (z0 * z0).
        movprfx z0, p0, z0              // Remove the .d suffix (MOVPRFX takes a plain Z register).
        st1d    {z0.d}, p0, [x20]        // store the result vector back.

