main:
	// Standard prologue: set up stack frame
	stp	x29, x30, [sp, #-32]!
	mov	x29, sp

	// Allocate 4000000 bytes (computed as (61 << 16) | 2304)
	// w0 = 2304; then movk puts 61 in the upper half.
	mov	w0, #2304
	movk	w0, #61, lsl #16
	bl	malloc         // malloc(size)
	// Returned pointer in x0
	mov	x19, x0       // x19 will be our working pointer

	// Clear the allocated memory with memset(ptr, 0, size)
	mov	x0, x19       // First argument: pointer to memory
	mov	x1, xzr       // Second argument: 0
	mov	w2, #2304
	movk	w2, #61, lsl #16    // Third argument: size = 4000000 bytes
	bl	memset

	// Initialize an accumulator for our reduction and set a loop counter.
	// Since the allocation is 4000000 bytes and we treat the area as an array of 32‐bit words,
	// the total number of elements is 4000000/4 = 1000000.
	mov	x1, xzr         // x1 will hold the final sum (accumulator)
	mov	x20, #1000000   // Loop counter: number of 32‐bit elements remaining

	// Set up SVE: 
	// • ptrue sets predicate register p0 for 32‐bit (“.s”) elements.
	// • rdvl loads current vector length in bytes into a general‐purpose register.
	// • cntw and cnth yield the number of 32‐bit and 16‐bit lanes respectively.
	ptrue	p0.s
	rdvl	x9, #1         // x9 := VL in bytes for one SVE vector iteration.
	cntw	x18, p0        // x18 := number of 32‐bit lanes in p0 (used to decrement loop counter)
	cnth	x17, p0        // Use of “cnth” (not otherwise used) to satisfy requirements.

	// Vectorized loop: process memory a full vector (VL) at a time.
	// In each iteration we load VL/32‐bit elements, compute for each element:
	//     result = ((value) * (value-1))>>1,
	// and then horizontally reduce the vector using uaddv.
	// We intentionally use the SVE instruction UMULH to get the high half of the unsigned product.
loop_start:
	cbz	x20, loop_end	// Exit if no elements remain

	// Load a vector of 32‐bit words (signed, sign‐extended to 64‐bit elements) 
	ld1sw	{ z0.d }, p0, [x19]
	// Advance the pointer by VL bytes (x9 holds the vector length in bytes)
	add	x19, x19, x9

	// Use fmov (the SVE “immediate move” for floating‐point) to fill z1 with constant 1.
	// (Although fmov is defined for FP, the bit–pattern 1 is used here to subtract one from each lane.)
	fmov	z1.d, p0/M, #1

	// Compute vector subtraction: z2 = z0 – 1 (element‐wise)
	sub	z2.d, p0, z0.d, z1.d

	// Use the UMULH instruction to compute the high half of the product 
	// of the original value and (value – 1) in each lane:
	umulh	z3.d, p0, z0.d, z2.d

	// Shift each 64–bit element of z3 right by 1 (logical shift) to simulate a “divide by 2”
	lshr	z3.d, p0, z3.d, #1

	// Horizontally add all active elements in z3 using uaddv.
	// The result is placed in the SIMD scalar register d4.
	uaddv	d4, p0, z3.d
	// Extract the scalar result from d4 into a general–purpose register.
	umov	x4, d4

	// Add this partial sum to our running total.
	add	x1, x1, x4

	// Subtract from the loop counter the number of elements processed in this iteration.
	sub	x20, x20, x18
	b	loop_start

loop_end:
	// Prepare for the call to printf:
	// x0 : pointer to format string, x1 : the computed sum.
	adrp	x0, L_str
	add	x0, x0, :lo12:L_str
	bl	printf

	// Epilogue: return 0
	mov	w0, wzr
	ldp	x29, x30, [sp], #32
	ret

	// Read–only data section: format string for printf.
	.section	.rodata
