// predicate register P0; it obtains the current vector length in bytes
// via RDVL and computes the number of int32 “lanes” per iteration.
// In Loop A the buffer is updated (each element is “shifted right” then
// incremented by 1) and a dummy reduction is done with UADDV (whose result
// is moved by FMOV) to show use of those instructions.
// In Loop B the code subtracts 1 from each element and uses CMPLo to compare
// (unsigned “lower than 10”) then uses CNTH to count how many lanes satisfy
// the condition. The final count is printed by printf.

        .text
        .global main
        .p2align 2
main:
        // Prologue: standard stack frame setup.
        stp     x29, x30, [sp, #-32]!
        mov     x29, sp
        stp     x28, x19, [sp, #-16]    // Save x28 and x19

        // Allocate a large buffer on the stack.
        // (Mirroring the original subtractions: "sub sp, sp, #976, lsl #12" then "sub sp, sp, #2320")
        sub     sp, sp, #976, lsl #12
        sub     sp, sp, #2320
        add     x19, sp, #12             // x19 points to the allocated buffer

