        // (Use x0 = buffer+4, w1 = 0, w2 = total size; the immediate is built by MOV and MOVK.)
        add     x0, x19, #4
        mov     w1, wzr
        mov     w2, #2304
        movk    w2, #61, lsl #16
        bl      memset

