		stp		x29, x30, [sp, #-32]!
		mov		x29, sp

		// Reserve a 64‐byte slot on the stack:
		// • 32 bytes to save the predicate register (p0)
		// • 32 bytes to hold temporary storage for the vector result.
		sub		sp, sp, #64

		// Initialize predicate register P0 with all active 32‐bit lanes.
		ptrue	p0.s

		// Save the predicate register.
		str		p0, [sp]

		// Later, reload it.
		ldr		p1, [sp]

		// Now compute element‐wise (over 32‑bit lanes):
		//    result = ((100 – 1) ÷ 2 & 0xff) * 3
		dup		z0.s, #100			// z0 = {100, 100, …}
		sub		z0.s, z0.s, #1		// z0 = {99, 99, …}
		dup		z1.s, #2			// z1 = {2, 2, …}
		udiv	z0.s, p1/m, z0.s, z1.s	// z0 = 99 ÷ 2 = 49 (integer division)
		and		z0.s, z0.s, #0xff	// mask: 49 remains 49
		mul		z0.s, z0.s, #3		// multiply: 49 * 3 = 147

