		// The temporary area is placed immediately above the predicate backup.
		// (i.e. at sp + 32 because the predicate backup is 32 bytes.)
		mov		x9, sp
		add		x9, x9, #32		// x9 = sp + 32
		st1w	{ z0.s }, p0, [x9]	// store the full vector to temporary storage
		ldr		w0, [sp, #32]		// load the first 32‐bit word of the result

