		adrp	x0, fmt_str
		add		x0, x0, :lo12:fmt_str
		bl		printf

		// Epilogue: restore stack and return.
		add		sp, sp, #64		// deallocate the 64-byte temporary area
		ldp		x29, x30, [sp], #32	// restore frame pointer and link register, adjust sp
		ret

